     3→import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
     4→
     5→type ConsentCategory = "essential" | "media" | "analytics";
     6→
     7→interface ConsentState {
     8→  essential: boolean;
     9→  media: boolean;
    10→  analytics: boolean;
    11→  version: string;
    12→  updatedAt: string;
    13→}
    14→
    15→type StoredConsent = ConsentState & { hasChoice?: boolean };
    16→
    17→interface ConsentContextValue {
    18→  state: ConsentState;
